from scipy.special import erf
def gelu(x): return 0.5*x*(1+erf(x/np.sqrt(2)))
F=np.load('feats.npz'); y=F['y']
C=F['C9']; M=F['M9']
Uc=np.linalg.svd(C-C.mean(0),full_matrices=False)[2]   # rows = PCs
Um=np.linalg.svd(M-M.mean(0),full_matrices=False)[2]
rM=468
E=Uc[768-rM:].T      # 768 x rM (bottom PCs of C9)
Wm=Um[:rM]           # rM x 768
def LN(X): X=X-X.mean(1,keepdims=True); return X/np.sqrt((X**2).mean(1,keepdims=True)+1e-12)
def mkfolds(seed):
    rng=np.random.RandomState(seed); f2=np.zeros(len(y),int)
    for c in range(8):
        idx=np.where(y==c)[0]; rng.shuffle(idx); f2[idx]=np.arange(len(idx))%5
    return f2
FS=[mkfolds(s) for s in [0,7,11]]
def evalx(X, lams_lin, gelu_params=None, lams_k=None, wlin=1.0):
    res_lin=np.zeros(len(lams_lin)); res_k={}
    for fo in FS:
        for f in range(5):
            tr=fo!=f; te=~tr
            mu=X[tr].mean(0); sd=X[tr].std(0)+1e-6; Z=(X-mu)/sd
            Y=np.eye(8)[y[tr]]-1/8
            K=Z@Z[tr].T; ev,U=np.linalg.eigh(K[tr]); UtY=U.T@Y
            for i,l in enumerate(lams_lin):
                a=U@(UtY/(ev+l)[:,None]); res_lin[i]+=(np.argmax(K[te]@a,1)==y[te]).sum()
            if gelu_params:
                S=Z@Z[tr].T/Z.shape[1]
                for (beta,theta) in gelu_params:
                    Phi=gelu(beta*S-theta); Phi=Phi-Phi[tr].mean(0)
                    G=np.concatenate([wlin*Z/np.sqrt(Z.shape[1]),Phi],1)
                    Kg=G@G[tr].T; ev2,U2=np.linalg.eigh(Kg[tr]); UtY2=U2.T@Y
                    for l in lams_k:
                        a=U2@(UtY2/(ev2+l)[:,None]); res_k[(beta,theta,l)]=res_k.get((beta,theta,l),0)+(np.argmax(Kg[te]@a,1)==y[te]).sum()
    n=len(FS)*len(y)
    return np.round(res_lin/n,4), {k:round(v/n,4) for k,v in res_k.items()}
for kap in [0.5,1.0,2.0]:
    X=LN(C + kap*((M-M.mean(0))@Wm.T)@E.T)
    rl,_=evalx(X,[200,300,500,800])
    print('kappa',kap,'linear on x',rl)
np.save('design_E_Wm.npy',np.stack([E.T,Wm]))
